<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Canvas Billiards</title>
<style>
  :root { color-scheme: dark; }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    display: grid;
    place-items: center;
    background:
      radial-gradient(circle at 50% 20%, #25303a, #10151b 70%);
    color: #f4f1df;
    font-family: system-ui, -apple-system, Segoe UI, sans-serif;
  }
  .wrap {
    width: min(96vw, 980px);
    text-align: center;
  }
  h1 {
    margin: 0 0 8px;
    font-size: clamp(20px, 3vw, 30px);
    letter-spacing: .08em;
    text-transform: uppercase;
  }
  .instructions {
    margin: 0 auto 12px;
    padding: 8px 14px;
    width: fit-content;
    max-width: 100%;
    border: 1px solid #a99157;
    border-radius: 999px;
    background: rgba(0,0,0,.3);
    color: #f4e7b5;
    font-size: 14px;
  }
  .table-shell {
    position: relative;
    width: 100%;
    padding: 18px;
    border-radius: 16px;
    background: linear-gradient(135deg, #b48747, #60401f 45%, #aa7740);
    box-shadow: 0 16px 40px #0009, inset 0 0 0 3px #d4a35c;
  }
  canvas {
    display: block;
    width: 100%;
    height: auto;
    border-radius: 5px;
    touch-action: none;
    cursor: crosshair;
  }
  .controls {
    margin-top: 12px;
    display: flex;
    justify-content: center;
    gap: 12px;
    align-items: center;
  }
  button {
    border: 1px solid #e0bc6e;
    border-radius: 7px;
    padding: 9px 18px;
    color: #fff8dc;
    background: linear-gradient(#80602d, #513916);
    font-weight: 700;
    cursor: pointer;
  }
  button:hover { filter: brightness(1.2); }
  #status { color: #d7d0b2; font-size: 13px; min-width: 150px; }
</style>
</head>
<body>
<div class="wrap">
  <h1>Corner Pocket</h1>
  <div class="instructions">
    Press on the white cue ball, drag backward to aim and set power, then release to shoot.
  </div>
  <div class="table-shell">
    <canvas id="table" width="900" height="500"></canvas>
  </div>
  <div class="controls">
    <button id="reset">Reset / Rack</button>
    <span id="status">Ready to break</span>
  </div>
</div>

<script>
(() => {
  "use strict";

  const canvas = document.getElementById("table");
  const ctx = canvas.getContext("2d");
  const W = 900, H = 500, R = 11;
  const pocketRadius = 23;
  const friction = 34;
  const cushionRestitution = 0.97;
  const ballRestitution = 1.0;
  const balls = [];
  let running = true;
  let raf = 0;
  let lastTime = performance.now();
  let dragging = false;
  let pointer = {x: 0, y: 0};
  let dragStart = {x: 0, y: 0};

  const pockets = [
    {x: 0, y: 0}, {x: W / 2, y: 0}, {x: W, y: 0},
    {x: 0, y: H}, {x: W / 2, y: H}, {x: W, y: H}
  ];

  function defaultRack() {
    const a = [];
    a.push({x: 225, y: H / 2, vx: 0, vy: 0, cue: true});
    const cx = 680, cy = H / 2;
    const spacing = R * 2.08;
    const colors = [
      "#e9c72f","#2069c9","#d83b32","#8b42a5","#ef8b28",
      "#299e5b","#b52d35","#171717","#e4c52e","#397bc5",
      "#da4238","#8843a0","#ec862b","#299a59","#a82932"
    ];
    let n = 0;
    for (let row = 0; row < 5; row++) {
      for (let j = 0; j <= row; j++) {
        a.push({
          x: cx + row * spacing * 0.866,
          y: cy + (j - row / 2) * spacing,
          vx: 0, vy: 0, cue: false, color: colors[n++ % colors.length]
        });
      }
    }
    return a;
  }

  function reset(input) {
    balls.length = 0;
    const source = Array.isArray(input) ? input : defaultRack();
    source.forEach((b, i) => {
      balls.push({
        x: Number(b.x) || 0,
        y: Number(b.y) || 0,
        vx: Number(b.vx) || 0,
        vy: Number(b.vy) || 0,
        cue: !!b.cue,
        potted: false,
        color: b.cue ? "#f7f5e8" : (b.color || [
          "#e9c72f","#2069c9","#d83b32","#8b42a5","#ef8b28",
          "#299e5b","#b52d35","#171717"
        ][i % 8])
      });
    });
    dragging = false;
    draw();
  }

  function step(dt) {
    dt = Number(dt);
    if (!Number.isFinite(dt) || dt <= 0) {
      draw();
      return;
    }
    // Small deterministic substeps prevent tunneling through balls and rails.
    const count = Math.max(1, Math.ceil(dt / 0.006));
    const h = dt / count;
    for (let s = 0; s < count; s++) physics(h);
    draw();
  }

  function physics(dt) {
    for (const b of balls) {
      if (b.potted) continue;
      b.x += b.vx * dt;
      b.y += b.vy * dt;

      const speed = Math.hypot(b.vx, b.vy);
      if (speed > 0) {
        const ns = Math.max(0, speed - friction * dt);
        if (ns === 0) b.vx = b.vy = 0;
        else {
          const k = ns / speed;
          b.vx *= k; b.vy *= k;
        }
      }

      for (const p of pockets) {
        if (Math.hypot(b.x - p.x, b.y - p.y) <= pocketRadius) {
          b.potted = true;
          b.vx = b.vy = 0;
          break;
        }
      }
      if (b.potted) continue;

      if (b.x < R) { b.x = R; if (b.vx < 0) b.vx = -b.vx * cushionRestitution; }
      if (b.x > W - R) { b.x = W - R; if (b.vx > 0) b.vx = -b.vx * cushionRestitution; }
      if (b.y < R) { b.y = R; if (b.vy < 0) b.vy = -b.vy * cushionRestitution; }
      if (b.y > H - R) { b.y = H - R; if (b.vy > 0) b.vy = -b.vy * cushionRestitution; }
    }

    // A couple of passes resolve chains of touching equal-mass balls.
    for (let pass = 0; pass < 2; pass++) {
      for (let i = 0; i < balls.length; i++) {
        const a = balls[i];
        if (a.potted) continue;
        for (let j = i + 1; j < balls.length; j++) {
          const b = balls[j];
          if (b.potted) continue;
          let dx = b.x - a.x, dy = b.y - a.y;
          let d2 = dx * dx + dy * dy;
          const minD = R * 2;
          if (d2 >= minD * minD) continue;
          let d = Math.sqrt(d2);
          if (d < 0.00001) {
            dx = 1; dy = 0; d = 1;
          } else {
            dx /= d; dy /= d;
          }

          const overlap = minD - d;
          // Equal positional correction keeps the collision stable.
          a.x -= dx * overlap * 0.5;
          a.y -= dy * overlap * 0.5;
          b.x += dx * overlap * 0.5;
          b.y += dy * overlap * 0.5;

          const rel = (b.vx - a.vx) * dx + (b.vy - a.vy) * dy;
          if (rel < 0) {
            const impulse = -(1 + ballRestitution) * rel / 2;
            a.vx -= impulse * dx;
            a.vy -= impulse * dy;
            b.vx += impulse * dx;
            b.vy += impulse * dy;
          }
        }
      }
    }
  }

  function shoot(vx, vy) {
    const cue = balls.find(b => b.cue && !b.potted);
    if (!cue) return;
    cue.vx = Number.isFinite(vx) ? vx : 0;
    cue.vy = Number.isFinite(vy) ? vy : 0;
  }

  function state() {
    return balls.map(b => ({
      x: b.x, y: b.y, vx: b.vx, vy: b.vy,
      potted: !!b.potted, cue: !!b.cue
    }));
  }

  function pause() {
    running = false;
    if (raf) cancelAnimationFrame(raf);
    raf = 0;
  }
  function resume() {
    if (!running) {
      running = true;
      lastTime = performance.now();
      raf = requestAnimationFrame(loop);
    }
  }
  function loop(now) {
    if (!running) return;
    const dt = Math.min(0.05, Math.max(0, (now - lastTime) / 1000));
    lastTime = now;
    if (dt) step(dt);
    raf = requestAnimationFrame(loop);
  }

  function draw() {
    // Deep green cloth with subtle stripes.
    const cloth = ctx.createLinearGradient(0, 0, W, H);
    cloth.addColorStop(0, "#126044");
    cloth.addColorStop(.5, "#0b704b");
    cloth.addColorStop(1, "#09543a");
    ctx.fillStyle = cloth;
    ctx.fillRect(0, 0, W, H);

    ctx.globalAlpha = .08;
    for (let x = -H; x < W + H; x += 28) {
      ctx.strokeStyle = "#d8f2bb";
      ctx.lineWidth = 8;
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x + H, H); ctx.stroke();
    }
    ctx.globalAlpha = 1;

    // Cushion rails.
    ctx.fillStyle = "#58391e";
    ctx.fillRect(0, 0, W, R);
    ctx.fillRect(0, H - R, W, R);
    ctx.fillRect(0, 0, R, H);
    ctx.fillRect(W - R, 0, R, H);

    for (const p of pockets) {
      const g = ctx.createRadialGradient(p.x, p.y, 2, p.x, p.y, pocketRadius);
      g.addColorStop(0, "#020303");
      g.addColorStop(.75, "#080b0b");
      g.addColorStop(1, "#231b13");
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(p.x, p.y, pocketRadius, 0, Math.PI * 2); ctx.fill();
    }

    if (dragging) {
      const cue = balls.find(b => b.cue && !b.potted);
      if (cue) {
        const dx = cue.x - pointer.x, dy = cue.y - pointer.y;
        const len = Math.hypot(dx, dy);
        if (len > 1) {
          const ux = dx / len, uy = dy / len;
          const guide = Math.min(420, len * 3.0);
          ctx.save();
          ctx.setLineDash([10, 8]);
          ctx.strokeStyle = "rgba(255,248,190,.9)";
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.moveTo(cue.x, cue.y);
          ctx.lineTo(cue.x + ux * guide, cue.y + uy * guide);
          ctx.stroke();
          ctx.restore();
          ctx.fillStyle = "rgba(255,255,220,.8)";
          ctx.font = "bold 13px system-ui";
          ctx.fillText("POWER " + Math.min(100, Math.round(len / 2.5)) + "%", 18, 28);
        }
      }
    }

    for (const b of balls) {
      if (b.potted) continue;
      const grad = ctx.createRadialGradient(
        b.x - R * .35, b.y - R * .4, 1, b.x, b.y, R * 1.2
      );
      grad.addColorStop(0, "#fff");
      grad.addColorStop(.22, b.color);
      grad.addColorStop(1, "#111");
      ctx.fillStyle = grad;
      ctx.beginPath(); ctx.arc(b.x, b.y, R, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = "rgba(0,0,0,.65)";
      ctx.lineWidth = 1;
      ctx.stroke();
      if (!b.cue && b.color !== "#171717") {
        ctx.fillStyle = "#fff";
        ctx.beginPath(); ctx.arc(b.x - 2, b.y - 2, 2.1, 0, Math.PI * 2); ctx.fill();
      }
    }
  }

  function mousePos(e) {
    const r = canvas.getBoundingClientRect();
    return {
      x: (e.clientX - r.left) * W / r.width,
      y: (e.clientY - r.top) * H / r.height
    };
  }

  canvas.addEventListener("pointerdown", e => {
    const p = mousePos(e);
    const cue = balls.find(b => b.cue && !b.potted);
    if (!cue || Math.hypot(p.x - cue.x, p.y - cue.y) > R + 9) return;
    dragging = true;
    dragStart = {x: cue.x, y: cue.y};
    pointer = p;
    canvas.setPointerCapture(e.pointerId);
    draw();
  });
  canvas.addEventListener("pointermove", e => {
    if (!dragging) return;
    pointer = mousePos(e);
    draw();
  });
  canvas.addEventListener("pointerup", e => {
    if (!dragging) return;
    pointer = mousePos(e);
    const dx = dragStart.x - pointer.x, dy = dragStart.y - pointer.y;
    const len = Math.hypot(dx, dy);
    if (len > 3) {
      const scale = Math.min(1250, len * 5.2) / Math.max(1, len);
      shoot(dx * scale, dy * scale);
    }
    dragging = false;
    draw();
  });
  canvas.addEventListener("pointercancel", () => { dragging = false; draw(); });
  document.getElementById("reset").addEventListener("click", () => {
    reset();
    document.getElementById("status").textContent = "Rack reset";
  });

  window.sim = { W, H, R, reset, step, state, shoot, pause, resume };
  reset();
  raf = requestAnimationFrame(loop);
})();
</script>
</body>
</html>
